Lemma spmm_lane_min_repair : forall vl lane x e v z bound mask,
 Binary.is_nan 24 128 bound=false ->
 spmm_active_value vl lane x e -> spmm_active_mask vl lane mask(spmm_nanth x) ->
 spmm_active_value vl lane v(fp32_min_number x bound) ->
 spmm_active_value vl lane z(spmm_merge v canonical_qnan mask) ->
 spmm_active_value vl lane z(fp32_neon_min e bound).
Proof.
 unfold spmm_active_value,spmm_active_mask,bit_same.
 intros vl lane x e v z bound mask Hnan Hx Hm Hv Hz Hl.
 rewrite Hz,Hv,Hm,Hx by assumption.
 rewrite spmm_min_merge by assumption;reflexivity.
Qed.
Lemma spmm_lane_max_repair : forall vl lane x e v z bound mask,
